  static String view(Node r) {
    List<Integer> a = new ArrayList<>();
    inorder(r, a);
    return a.toString();
  }

  static int balancedHeight(Node r) {
    if (r == null) return 0;
    int l = balancedHeight(r.left);
    if (l < 0) return -1;
    int q = balancedHeight(r.right);
